 * A thread-safe LRU cache implementation with O(1) get and put operations.
 */
public class LRUCache<K, V> {
    private final int capacity;
    private final ConcurrentHashMap<K, V> cache;
    private final ConcurrentLinkedQueue<K> queue;
    private final ReentrantLock lock;

    /**
     * Constructs a new LRU cache with the specified capacity.
     *
     * @param capacity the maximum number of items in the cache
     */
    public LRUCache(int capacity) {
        this.capacity = capacity;
        this.cache = new ConcurrentHashMap<>();
        this.queue = new ConcurrentLinkedQueue<>();
        this.lock = new ReentrantLock();
    }

    /**
     * Retrieves the value associated with the specified key.
     *
     * @param key the key to retrieve
     * @return the associated value, or null if not found
     */
    public V get(K key) {
        lock.lock();
        try {
            if (cache.containsKey(key)) {
                // Move the accessed key to the front of the queue
                queue.remove(key);
                queue.add(key);
                return cache.get(key);
            }
            return null;
        } finally {
            lock.unlock();
        }
    }

    /**
     * Associates the specified key with the specified value.
     *
     * @param key the key to associate
     * @param value the value to associate
     */
    public void put(K key, V value) {
        lock.lock();
