import random
import time
import functools

class CircuitBreaker:
    def __init__(self, threshold=5, window=60):
        self.threshold = threshold
        self.window = window
        self.failures = []
        self.circuit_open = False

    def record_failure(self):
        self.failures.append(time.time())
        self.failures = [f for f in self.failures if f > time.time() - self.window]
        if len(self.failures) >= self.threshold:
            self.circuit_open = True

    def is_open(self):
        if self.circuit_open:
            if time.time() - self.failures[-1] > self.window:
                self.circuit_open = False
                self.failures = []
            return True
        return False

def retry_with_exponential_backoff(max_retries, initial_delay, max_delay, jitter_factor, circuit_breaker):
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            delay = initial_delay
            for _ in range(max_retries):
                if circuit_breaker.is_open():
                    raise Exception('Circuit breaker is open')
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    circuit_breaker.record_failure()
                    delay = min(delay * 2, max_delay)
                    jitter = random.uniform(-jitter_factor * delay, jitter_factor * delay)
                    delay_with_jitter = delay + jitter
                    time.sleep(delay_with_jitter)
            raise Exception('Max retries exceeded')
        return wrapper
    return decorator

