===========================================================

Below is a JavaScript implementation of a function that compresses a string using Run-Length Encoding (RLE) and another function that decompresses the compressed string.

**RLE Compression Function**
---------------------------

```javascript
/**
 * Compresses a string using Run-Length Encoding (RLE).
 *
 * @param {string} str - The input string to be compressed.
 * @returns {string} The compressed string.
 */
function rleCompress(str) {
  if (!str || typeof str!== 'string') {
    throw new Error('Input must be a non-empty string.');
  }

  let compressed = '';
  let currentChar = str[0];
  let count = 1;

  for (let i = 1; i <= str.length; i++) {
    if (i === str.length || str[i]!== currentChar) {
      compressed += count + currentChar;
      if (i < str.length) {
        currentChar = str[i];
        count = 1;
      }
    } else {
      count++;
    }
  }

  return compressed;
}
```

**RLE Decompression Function**
---------------------------

```javascript
/**
 * Decompresses a string that was previously compressed using Run-Length Encoding (RLE).
 *
 * @param {string} str - The compressed string to be decompressed.
 * @returns {string} The decompressed string.
 */
function rleDecompress(str) {
  if (!str || typeof str!== 'string') {
    throw new Error('Input must be a non-empty string.');
  }

  let decompressed = '';
  let i = 0;

  while (i < str.length) {
    let count = '';
    while (i < str.length &&!isNaN(str[i])) {
      count += str[i++];
    }
    const char = str[i++];
    decompressed += char.repeat(parseInt(count));
  }

  return decompressed;
}
```

